<script setup lang="ts">
import { ArrowLeft, Heart, Check, MapPin, Clock, ArrowUpRight } from 'lucide-vue-next'
import { attributeLabels, priceLabel, genres, type Restaurant } from '../../../shared/domain'
const route=useRoute();const app=useApp();const {data:r,error,refresh}=await useFetch<Restaurant & {google:Record<string,any>|null;googleUnavailable:boolean}>(`/api/restaurants/${encodeURIComponent(String(route.params.slug))}`)
const mapUrl=computed(()=>r.value?.google?.googleMapsUri||`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(r.value?.demo?`大阪 ${r.value.area}`:`大阪 ${r.value?.name}`)}${r.value?.placeId?`&query_place_id=${encodeURIComponent(r.value.placeId)}`:''}`)
useSeoMeta({title:()=>`${r.value?.name||'店舗詳細'} | ひとくち大阪`,description:()=>r.value?.description,ogImage:()=>r.value?.coverImageUrl})
</script>
<template><section class="page detail-page"><NuxtLink to="/recommendations" class="text-link"><ArrowLeft :size="16"/>おすすめに戻る</NuxtLink><div v-if="error" class="empty-state"><h1>店舗情報を取得できませんでした</h1><button class="button primary" @click="refresh()">再試行</button></div><template v-if="r"><div class="detail-layout"><div><img class="detail-hero" :src="r.coverImageUrl" :alt="`${r.name}の料理${r.demo?'イメージ':''}`"/><div v-if="r.images.length" class="gallery"><figure v-for="i in r.images" :key="i.url"><img :src="i.url" :alt="i.alt" loading="lazy"/><figcaption>{{i.credit}}</figcaption></figure></div></div><div class="detail-copy"><div class="eyebrow"><MapPin :size="14"/> OSAKA / {{r.area}}</div><h1>{{r.name}}</h1><p class="detail-catch">{{r.recommendationText}}</p><div class="chips display-tags"><span v-for="g in r.genres" :key="g">{{genres.find(x=>x.key===g)?.label||g}}</span><span v-for="key in Object.keys(r.attributes)" :key="key">{{attributeLabels[key]||key}}</span></div><p class="detail-description">{{r.description}}</p><dl class="info-table"><div><dt>予算目安</dt><dd>{{priceLabel(r)}} / 人</dd></div><div><dt><MapPin :size="15"/>住所</dt><dd>{{r.google?.formattedAddress||(r.demo?`大阪市 ${r.area}エリア（架空店舗のため住所はありません）`:'現在、住所を取得できません')}}</dd></div><div><dt><Clock :size="15"/>営業時間</dt><dd><template v-if="r.google?.regularOpeningHours?.weekdayDescriptions"><div v-for="line in r.google.regularOpeningHours.weekdayDescriptions" :key="line">{{line}}</div></template><template v-else>{{r.demo?'デモ店舗のため営業していません':'Googleマップで最新情報をご確認ください'}}</template></dd></div></dl><p v-if="r.google" class="muted">住所・営業時間の情報提供：Google Maps</p><p v-if="r.googleUnavailable" class="notice">最新情報を取得できませんでした。営業状況はGoogleマップでご確認ください。</p><div class="detail-actions"><button class="button primary" @click="app.favorite(r)"><Heart :size="18" :fill="app.history.value.favorites.includes(r.id)?'currentColor':'none'"/>{{app.history.value.favorites.includes(r.id)?'保存済み・解除':'気になる'}}</button><button class="button secondary" @click="navigateTo(`/feedback/${app.visit(r)}`)"><Check :size="18"/>行った</button></div><a :href="mapUrl" target="_blank" rel="noopener noreferrer" class="button map-link">Googleマップで{{r.demo?'エリアを':'見る'}} <ArrowUpRight :size="18"/></a></div></div><RestaurantMap :location="r.google?.location" :name="r.name" :url="mapUrl"/></template></section></template>
